    "correctAnswer": "B",
    "justification": "Classificação dos bens públicos (Art. 99 CC): (1) Uso comum do povo (rios, mares, estradas, praças); (2) Uso especial (escolas, hospitais, repartições, viaturas); (3) Dominicais (patrimônio disponível sem afetação — únicos alienáveis cumprindo Art. 76 da Lei 14.133/21: interesse público, avaliação, autorização legislativa para imóveis e leilão). TODOS são impenhoráveis e imprescritíveis (sem usucapião - Súmula 340 STF).",
