        "code": "Lei nº 14.133/2021 / CF/88",
        "article": "Arts. 18 a 21 e 56 a 65 da Lei nº 9.784/1999",
        "textSnippet": "Na Lei nº 9.784/99: Impedimento (Art. 18 — interesse, testemunha/perito/procurador ou cônjuge/parente até 3º grau, litígio judicial/adm.) deve ser comunicado pelo próprio servidor; Suspeição (Art. 20 — amizade íntima ou inimizade notória). Recurso: prazo 10 dias (Art. 59), até 3 instâncias (Art. 57), sem depósito prévio (SV 21), admite agravamento após ciência prévia (Art. 64, par. único); já a REVISÃO por fatos novos PROÍBE agravamento da sanção (Art. 65, par. único)!"
