    "professorTip": "Lei Anticorrupção (12.846/13): PJ responde OBJETIVAMENTE! Multa = 0,1% a 20% do faturamento bruto! Leniência reduz multa até 2/3, mas NÃO livra de reparar integralmente o dano!"
