        "textSnippet": "Na Lei nº 12.527/2011 (LAI): transparência ativa e passiva sem exigir motivação (Art. 10, § 3º); fornecimento imediato ou em até 20 dias (+ 10 dias justificados — Art. 11). Classificação sigilosa: Reservado (5 anos), Secreto (15 anos), Ultrassecreto (25 anos). Informações pessoais (intimidade/honra): 100 anos."
