    "professorTip": "LAI (12.527/11): NÃO precisa dizer o motivo! Prazo de resposta: imediato ou 20 dias (+10)! Sigilo: Reservado = 5 anos, Secreto = 15 anos, Ultrassecreto = 25 anos, Pessoal = 100 anos!"
