        "article": "Arts. 17, 29 e 69 da Lei nº 13.303/2016",
        "textSnippet": "Na Lei nº 13.303/2016 (Estatuto das Estatais): rege empresas públicas, sociedades de economia mista e suas subsidiárias (inclusive contratação com dispensa própria do Art. 29 e hipóteses de inaplicabilidade de licitação do Art. 28, § 3º, no objeto social/oportunidade de negócio). Contratos têm matriz privada (alteração por acordo das partes dentro dos limites de 25%/50%, Art. 81) e prazo máximo ordinário de 5 anos (Art. 71)."
