    "statement": "Concessionária de rodovia federal passou a descumprir reiteradamente cláusulas contratuais de manutenção e segurança viária; em outro trecho, o poder concedente decidiu retomar o serviço de concessionária adimplente por motivo de interesse público superveniente. Quais são as formas de extinção aplicáveis?",
