    "justification": "Lei 11.079/04 (PPP): valor mínimo >= R$ 10 milhões; prazo >= 5 e <= 35 anos; veda objeto único de mão de obra/equipamento/obra pública. Concessão Patrocinada = tarifa + contraprestação pública; Concessão Administrativa = Estado é usuário direto/indireto (100% contraprestação pública).",
