        "letter": "B",
        "explanation": "Concessão patrocinada envolve cobrança de tarifa dos usuários + contraprestação pecuniária do parceiro público; quando não há tarifa de usuário (o Estado paga integralmente), é concessão ADMINISTRATIVA."
