        "textSnippet": "Na LGPD (Lei 13.709/18, Arts. 7º, III, e 23–26), o Poder Público não precisa de consentimento para tratar dados visando à execução de políticas públicas legais ou obrigação legal, mas se sujeita aos princípios da finalidade, adequação, transparência, indicação de encarregado e restrição de compartilhamento com privados."
