        "code": "Lei nº 14.133/2021 / CF/88",
        "article": "Art. 5º, XXII e XXIV, da CF/88 e DL 3.365/1941",
        "textSnippet": "Limitação administrativa: ato normativo geral e abstrato sem indenização (ex.: recuo de construção). Desapropriação indireta: apossamento administrativo ilícito sem processo prévio -> não devolve o bem já afetado (Art. 35 DL 3.365/41), cabendo indenização (prescrição 10 anos — STJ Tema 1019)."
