    "statement": "Jornalista solicita a ministério informações de interesse coletivo não classificadas como sigilosas. Qual o prazo máximo que o órgão tem para responder quando não for possível o acesso imediato, e qual o prazo máximo de restrição de acesso para documentos classificados como ultrassecretos?",
