    "professorTip": "PATI: Presunção = TODOS! Imperatividade = SÓ impositivos (não certidão/licença)! Autoexecutoriedade = só lei/urgência (Apreender alimento = SIM; Penhorar para cobrar multa = NÃO, só execução fiscal)!"
